#include <stdio.h>
int main(void) {
    int N = 8, L = 4;
    int A[8] = {1,2,3,4,5,6,7,8};
    int B[8] = {10,10,10,10,10,10,10,10};
    int C[8];
    int g, lid, i;
    for (g = 0; g < N / L; g++) {
        for (lid = 0; lid < L; lid++) {
            i = g * L + lid;
            C[i] = A[i] + B[i];
        }
    }
    printf("work-groups = %d\n", N / L);
    printf("last global id = %d\n", N - 1);
    printf("C[6] = %d\n", C[6]);
    return 0;
}
